import{at as e,it as t,n,vt as r}from"./chunks/framework.yntlMcNk.js";var i=JSON.parse(`{"title":"Navigationsbaum","description":"","frontmatter":{"title":"Navigationsbaum","covers":{"screens":["SCR-055"],"stories":["US-054"]}},"headers":[],"relativePath":"de/usage/navigation.md","filePath":"de/usage/navigation.md"}`),a={name:`de/usage/navigation.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="navigationsbaum" tabindex="-1">Navigationsbaum <a class="header-anchor" href="#navigationsbaum" aria-label="Permalink to “Navigationsbaum”">​</a></h1><p>Der Navigationsbaum ordnet Kataloge in Ordnern, zum Beispiel <em>IT Landscape &gt; Application Inventory</em>, damit du den Katalog für deine Aufgabe findest, ohne die Katalogliste zu durchsuchen. Alle mit der Berechtigung <code>entity:read</code> (zum Beispiel die Rolle <code>viewer</code>) sehen den Baum. Ändern lässt er sich mit der Berechtigung <code>viewpoint:manage</code> (Rolle <code>enterprise-architect</code>).</p><h2 id="die-seitenleiste" tabindex="-1">Die Seitenleiste <a class="header-anchor" href="#die-seitenleiste" aria-label="Permalink to “Die Seitenleiste”">​</a></h2><p>Nach der Anmeldung zeigt die Seitenleiste links auf jeder Seite den Baum. Er beginnt beim Ordner <em>Repository</em>.</p><ul><li><strong>Ordner auf- und zuklappen:</strong> Wähle den Pfeil oder den Namen des Ordners. Die Seitenleiste merkt sich die offenen Ordner, bis du den Browser-Tab schliesst.</li><li><strong>Katalog öffnen:</strong> Wähle seinen Eintrag. Der Katalog öffnet sich mit seiner Standardansicht, falls er eine hat (siehe <a href="./catalogs#views">Ansichten</a>).</li><li><strong>Schmale Bildschirme:</strong> Die Seitenleiste ist ausgeblendet; die Menü-Schaltfläche links in der Kopfzeile öffnet sie. Wählst du einen Katalog, schliesst sie sich wieder.</li></ul><p>Ordner und Kataloge sind nach Namen sortiert, unabhängig von Gross- und Kleinschreibung. Ein Eintrag zeigt seinen Anzeigenamen, falls er einen hat, sonst den Namen des Katalogs. Ein Personen-Symbol kennzeichnet einen persönlichen Katalog.</p><h2 id="ordner" tabindex="-1">Ordner <a class="header-anchor" href="#ordner" aria-label="Permalink to “Ordner”">​</a></h2><p>Mit <code>viewpoint:manage</code> bietet die Schaltfläche <em>…</em> neben einem Ordner:</p><ul><li><strong>Neuer Ordner:</strong> legt einen Ordner darin an. Gib einen Namen ein und wähle <em>Erstellen</em>.</li><li><strong>Umbenennen:</strong> ändert den Namen des Ordners, auch des Ordners <em>Repository</em>. Seine Einträge und Unterordner bleiben.</li><li><strong>Löschen:</strong> fragt zuerst nach und nennt, wie viele Unterordner und Einträge das Löschen entfernt. Der Ordner wird mit allen Unterordnern und Einträgen gelöscht. <strong>Kein Katalog wird gelöscht</strong>; die Kataloge bleiben in der Katalogliste und in anderen Ordnern. Der Ordner <em>Repository</em> lässt sich nicht löschen.</li></ul><p>Ein Ordnername hat 1 bis 255 Zeichen und ist in seinem Ordner eindeutig, unabhängig von Gross- und Kleinschreibung; sonst meldet der Dialog <em>Ein Ordner mit diesem Namen existiert bereits</em>. Der Baum hat höchstens 10 Ebenen unter <em>Repository</em> und höchstens 500 Ordner.</p><h2 id="katalog-einordnen" tabindex="-1">Katalog einordnen <a class="header-anchor" href="#katalog-einordnen" aria-label="Permalink to “Katalog einordnen”">​</a></h2><ol><li>Öffne den Katalog und wähle <em>In Navigation einordnen</em> (braucht <code>viewpoint:manage</code>).</li><li>Wähle unter <em>Ordner</em> den Ordner über seinen Pfad, zum Beispiel <em>Repository / IT Landscape</em>.</li><li>Gib bei Bedarf einen <em>Anzeigenamen</em> ein. Der Baum zeigt ihn dann statt des Katalognamens, zum Beispiel <em>System Inventory</em> für <em>Application Inventory</em>. Der Katalog behält seinen Namen.</li><li>Wähle <em>Einordnen</em>.</li></ol><p>Ein Katalog kann in mehreren Ordnern stehen, aber nur einmal pro Ordner; ein zweites Einordnen in denselben Ordner meldet <em>Der Katalog ist bereits in diesem Ordner</em>. Ein Ordner hat höchstens 200 Einträge.</p><h2 id="katalog-aus-dem-baum-entfernen" tabindex="-1">Katalog aus dem Baum entfernen <a class="header-anchor" href="#katalog-aus-dem-baum-entfernen" aria-label="Permalink to “Katalog aus dem Baum entfernen”">​</a></h2><p>Mit <code>viewpoint:manage</code> entfernt die Schaltfläche <em>×</em> neben einem Eintrag diesen aus dem Ordner. Nur dieser Eintrag verschwindet: Der Katalog selbst und seine Einträge in anderen Ordnern bleiben.</p><h2 id="personliche-kataloge" tabindex="-1">Persönliche Kataloge <a class="header-anchor" href="#personliche-kataloge" aria-label="Permalink to “Persönliche Kataloge”">​</a></h2><p>Deinen eigenen persönlichen Katalog kannst du wie einen geteilten einordnen. Nur du siehst seinen Eintrag: Der Baum zeigt nie persönliche Kataloge anderer Personen und führt so nie zu einem Katalog, den du nicht öffnen kannst. Teilst du den Katalog später, sehen alle den Eintrag.</p><p>Jede Änderung des Baums wird im Audit-Trail festgehalten.</p><h2 id="uber-die-api" tabindex="-1">Über die API <a class="header-anchor" href="#uber-die-api" aria-label="Permalink to “Über die API”">​</a></h2><ul><li><code>GET /views/explorer</code> liefert den Baum ab der Wurzel, so wie du ihn siehst: jeden Ordner mit <code>id</code>, <code>name</code>, <code>parentId</code>, <code>items</code> und <code>children</code>; jeden Eintrag mit <code>referenceId</code> (der Katalog-ID), <code>displayLabel</code>, <code>name</code> (dem aktuellen Namen des Katalogs) und <code>scope</code>.</li><li><code>POST /tree-nodes</code> mit <code>name</code> und <code>parentId</code> legt einen Ordner an; <code>PATCH /tree-nodes/{nodeId}</code> mit <code>name</code> benennt ihn um; <code>DELETE /tree-nodes/{nodeId}</code> löscht ihn.</li><li><code>POST /tree-nodes/{nodeId}/items</code> mit <code>itemType: catalog</code>, <code>referenceId</code> und optional <code>displayLabel</code> ordnet einen Katalog ein; <code>DELETE /tree-nodes/{nodeId}/items/{itemId}</code> entfernt den Eintrag.</li></ul><p>Jede Änderung antwortet mit dem ganzen Baum. Ungültige Eingaben werden mit 422 abgelehnt und nennen das Feld in <code>invalidFields</code>, zum Beispiel <code>name</code> für einen vergebenen Ordnernamen oder <code>referenceId</code> für einen zweiten Eintrag im selben Ordner.</p>`,21)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};